//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_STORAGE_USAGE_FLAG(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.STORAGE_USAGE_FLAG
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.STORAGE_USAGE_FLAG_SET.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.STORAGE_USAGE_FLAG
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.STORAGE_USAGE_FLAG_SET, dec)
	})
}
